20	  async function loadWorksheetData(worksheetName: string): Promise<void> {
21	    dataStore.worksheetState = 'loading';
22	    try {
23	      dataStore.worksheetRows = await getWorksheetData(worksheetName);
24	      dataStore.worksheetState = 'done';
25	    } catch {
26	      // Generic message — never expose raw error details to the consultant (AC4)
27	      dataStore.worksheetError = 'Could not load worksheet data';
28	      dataStore.worksheetState = 'error';
29	    }
30	  }
