32	  async function loadTasks(): Promise<void> {
33	    dataStore.tasksState = 'loading';
34	    try {
35	      const response = await apiFetch<{ data: Array<{ text: string }> }>('/api/data/tasks', {
36	        headers: sessionHeaders(),
37	      });
38	      dataStore.tasks = response.data;
39	      dataStore.tasksState = 'done';
40	    } catch (err) {
41	      const msg =
42	        err instanceof ApiError
43	          ? err.message
44	          : err instanceof Error
45	            ? err.message
46	            : 'Could not load task list';
47	      dataStore.tasksError = msg;
48	      dataStore.tasksState = 'error';
49	    }
50	  }
51	
52	  onMount(() => {
53	    let active = true; // abort guard — prevents stale promise writes on rapid remount
54	
55	    (async () => {
56	      // Distinguish config fetch failure from worksheet simply not being configured
57	      let worksheetName: string | null = null;
58	      let configFetchError: string | null = null;
59	      try {
60	        worksheetName = await loadWorksheetConfig();
61	      } catch (err) {
62	        configFetchError =
63	          err instanceof ApiError ? err.message : 'Could not load configuration';
64	      }
65	
66	      if (!active) return;
67	
68	      // Both fetches run independently — one failure must not block the other (NFR9)
69	      const worksheetPromise = worksheetName
70	        ? loadWorksheetData(worksheetName)
71	        : (() => {
72	            dataStore.worksheetError = configFetchError ?? 'Worksheet name not configured';
73	            dataStore.worksheetState = 'error';
74	            return Promise.resolve();
75	          })();
76	
77	      await Promise.allSettled([worksheetPromise, loadTasks()]);
78	    })();
79	
80	    return () => {
81	      active = false; // cancel on unmount
82	    };
83	  });
