2	  import { onMount } from 'svelte';
3	  import { initializeExtension, getTableauUserId } from './lib/tableau';
4	  import { apiFetch, ApiError } from './lib/api';
5	  import { sessionStore } from './stores/session.svelte';
6	  import { statusStore } from './stores/status.svelte';
7	  import StatusBar from './components/StatusBar.svelte';
8	  import AdminConfig from './components/AdminConfig.svelte';
9	  import DataPanel from './components/DataPanel.svelte';
10	  import OpenWorkPanel from './components/OpenWorkPanel.svelte';
11	  import ChatPanel from './components/ChatPanel.svelte';
12	
13	  const isAdminView = new URLSearchParams(window.location.search).has('admin');
14	
15	  type AppStatus = 'loading' | 'ready' | 'error';
16	
17	  let appStatus = $state<AppStatus>('loading');
18	  let errorMessage = $state('');
19	
20	  onMount(async () => {
21	    try {
22	      // Step 1: Initialize Tableau runtime
23	      await initializeExtension();
24	
25	      // Step 2: Get Tableau user identity
26	      const tableauUserId = getTableauUserId();
27	      sessionStore.tableauUserId = tableauUserId;
28	
29	      // Step 3: Create backend session
30	      const sessionResponse = await apiFetch<{
31	        data: { session_id: string; started_at: string };
32	      }>('/api/sessions', {
33	        method: 'POST',
34	        body: JSON.stringify({ tableau_user_id: tableauUserId }),
35	      });
36	      sessionStore.sessionId = sessionResponse.data.session_id;
37	
38	      // Step 4: Fetch integration statuses
39	      statusStore.loading = true;
40	      const sessionHeaders: Record<string, string> = {};
41	      if (sessionStore.sessionId) {
42	        sessionHeaders['X-Autom9-Session'] = sessionStore.sessionId;
43	      }
44	      const statusResponse = await apiFetch<{
45	        data: { integrations: Array<{ name: string; status: string; latency_ms: number | null; error: string | null }> };
46	      }>('/api/status', {
47	        headers: sessionHeaders,
48	      });
49	
50	      statusStore.integrations = statusResponse.data.integrations.map((i) => ({
51	        name: i.name,
52	        status: i.status as 'healthy' | 'unavailable',
53	        latency_ms: i.latency_ms,
54	        error: i.error,
55	      }));
56	      statusStore.loading = false;
57	
58	      appStatus = 'ready';
59	    } catch (err) {
60	      statusStore.loading = false;
61	      const msg = err instanceof Error ? err.message : 'Extension failed to initialize';
62	      errorMessage = msg;
63	      statusStore.error = msg;
64	      appStatus = 'error';
65	    }
66	  });
67	</script>
